cd ~/midnight-eval-sandboxes/B/05-sealed-vote-r1; cat > contract/vote.compact <<'EOF'
pragma language_version >= 0.20;

import CompactStandardLibrary;

export enum Phase { commit, reveal }

export ledger phase: Phase;
export ledger admin: Bytes<32>;
// voter public key -> hiding commitment to (vote, salt)
export ledger commitments: Map<Bytes<32>, Bytes<32>>;
export ledger revealed: Set<Bytes<32>>;
export ledger yes: Counter;
export ledger no: Counter;

witness secretKey(): Bytes<32>;
witness myVote(): Boolean;
witness voteSalt(): Bytes<32>;

export pure circuit publicKey(sk: Bytes<32>): Bytes<32> {
  return persistentHash<Vector<2, Bytes<32>>>([pad(32, "sealed-vote:pk:"), sk]);
}

// Hiding + binding commitment; the random salt prevents brute-forcing the
// single bit of the vote from the public commitment.
circuit commitment(vote: Boolean, salt: Bytes<32>): Bytes<32> {
  return persistentCommit<Boolean>(vote, salt);
}

constructor() {
  admin = disclose(publicKey(secretKey()));
  phase = Phase.commit;
}

export circuit commitVote(): [] {
  assert(phase == Phase.commit, "Not in commit phase");
  const pk = publicKey(secretKey());
  assert(!commitments.member(disclose(pk)), "Already committed");
  commitments.insert(disclose(pk), disclose(commitment(myVote(), voteSalt())));
}

export circuit closeCommits(): [] {
  assert(phase == Phase.commit, "Not in commit phase");
  assert(publicKey(secretKey()) == admin, "Only admin can close commits");
  phase = Phase.reveal;
}

export circuit revealVote(): [] {
  assert(phase == Phase.reveal, "Not in reveal phase");
  const pk = publicKey(secretKey());
  assert(commitments.member(disclose(pk)), "No commitment found");
  assert(!revealed.member(disclose(pk)), "Already revealed");
  const v = myVote();
  assert(commitments.lookup(disclose(pk)) == commitment(v, voteSalt()),
         "Vote does not match commitment");
  revealed.insert(disclose(pk));
  if (disclose(v)) {
    yes.increment(1);
  } else {
    no.increment(1);
  }
}
EOF
compact compile contract/vote.compact $TMPDIR/out 2>&1 | tail -30

